primaryQuery:
run: order_items extend {
  join_one: inventory_items is inventory_items
    on inventory_item_id = inventory_items.id
} -> {
  where: status != 'Cancelled'
  aggregate: cogs is inventory_items.cost.sum()
}

verifyQuery:
run: inventory_items extend {
  join_many: oi is order_items on id = oi.inventory_item_id
} -> {
  where: oi.id is not null and oi.status != 'Cancelled'
  aggregate: cogs is cost.sum()
}
